mapper.select:
SELECT * FROM ( SELECT FBM.YYYYMM , DV.DIVISION_NAME , IM.ITEM_CODE AS PRODUCT_CODE , IM.ITEM_NAME AS PRODUCT_NAME , FBM.HS_CODE FROM FTA_BOM_MST FBM INNER JOIN DIVISION DV ON DV.DIVISION_CODE = FBM.DIVISION_CODE AND DV.COMPANY_CODE = FBM.COMPANY_CODE AND DV.STATUS = 'Y' INNER JOIN ITEM_MST IM ON IM.ITEM_CODE = FBM.PRODUCT_CODE AND IM.COMPANY_CODE = FBM.COMPANY_CODE WHERE FBM.COMPANY_CODE = #{company_code} ) WHERE 1=1
AND YYYYMM BETWEEN #{from_date} AND #{to_date}
AND (PRODUCT_CODE ILIKE '%' || #{product} || '%' OR PRODUCT_NAME ILIKE '%' || #{product} || '%' )
AND DIVISION_CODE = #{division_code}

SELECT * FROM ( SELECT , IM.ITEM_CODE , IM.ITEM_NAME , IM.UNIT , FBD.HS_CODE , FBD.INPUT_QTY FROM FTA_BOM_DTL FBD INNER JOIN DIVISION DV ON DV.DIVISION_CODE = FBM.DIVISION_CODE AND DV.COMPANY_CODE = FBM.COMPANY_CODE AND DV.STATUS = 'Y' INNER JOIN ITEM_MST IM ON IM.ITEM_CODE = FBM.PRODUCT_CODE AND IM.COMPANY_CODE = FBM.COMPANY_CODE WHERE FBM.COMPANY_CODE = #{company_code}
AND FBD.YYYYMM = #{yyyymm}
AND FBD.PRODUCT_CODE = #{product_code}
AND FBD.DIVISION_CODE = #{division_code}
) WHERE 1=1
